const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Expect x: [N, C, H, W, D], weight: [Cout, Cin, K, K]
    const gert::Shape* x0 = context->GetInputShape(0);
    const gert::Shape* w0 = context->GetInputShape(1);
    if (GetRank(x0) != 5 || GetRank(w0) != 4) {
        return ge::GRAPH_FAILED;
    }

    uint32_t n    = static_cast<uint32_t>(GetDim(x0, 0));
    uint32_t c_in = static_cast<uint32_t>(GetDim(x0, 1));
    uint32_t h    = static_cast<uint32_t>(GetDim(x0, 2));
    uint32_t w    = static_cast<uint32_t>(GetDim(x0, 3));
    uint32_t d    = static_cast<uint32_t>(GetDim(x0, 4));

    uint32_t c_out = static_cast<uint32_t>(GetDim(w0, 0));
    uint32_t k     = static_cast<uint32_t>(GetDim(w0, 2)); // square kernel KxK, depth kernel is 1 at model side

    // Only support stride=1, padding=0, dilation=1 for this sample kernel
    uint32_t hout = (h >= k) ? (h - k + 1) : 0;
    uint32_t wout = (w >= k) ? (w - k + 1) : 0;

    ConvStandard3dAsymmetricInputSquareKernelCustomTilingData tiling;
    context->SetBlockDim(BLOCK_DIM);
    tiling.set_n(n);
    tiling.set_c_in(c_in);
    tiling.set_c_out(c_out);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_d(d);
    tiling.set_k(k);
    tiling.set_hout(hout);
    tiling.set_wout(wout);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

